package dev.horizonlab.parity;
import com.google.gson.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import net.minecraft.core.component.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.InteractionHand;
/** Real player equipment and inherited hand access through its selected slot. */
public final class VanillaPlayerEquipmentOracle {
 static final class Stop extends RuntimeException {}
 static Object unsafe;static Method allocate;static Field count,eqItems,inventory,entityEquipment;static Item[] items;
 static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
 static <T>T make(Class<T> c)throws Exception{return c.cast(allocate.invoke(unsafe,c));}
 static int n(JsonObject o,String k){return o.get(k).getAsInt();}
 static int type(Item item){for(int i=0;i<items.length;i++)if(items[i]==item)return i;throw new AssertionError();}
 static final class Data {
  PrintWriter out;JsonObject op;ItemStack[] refs;Inventory inv;PlayerEquipment equipment;Actor actor;int calls;IdentityHashMap<ItemStack,Integer> ids=new IdentityHashMap<>();
  int id(ItemStack s){return ids.computeIfAbsent(s,k->ids.size());}
  String snapshot(ItemStack s){try{return id(s)+":"+type(s.getItem())+":"+count.getInt(s)+":"+s.getCount()+":"+s.getPopTime()+":"+s.isEmpty();}catch(Exception e){throw new AssertionError(e);}}
  void all(){try{for(int i=0;i<refs.length;i++)out.println("ref "+i+" "+snapshot(refs[i]));out.println("state "+inv.getSelectedSlot()+" "+calls+" "+equipment.isEmpty());var slots=new StringJoiner(" | ");for(int i=0;i<43;i++)slots.add(snapshot(inv.getItem(i)));out.println("slots "+slots);var entries=new StringJoiner(" | ");for(var e:((EnumMap<EquipmentSlot,ItemStack>)eqItems.get(equipment)).entrySet())entries.add(e.getKey().name()+"="+snapshot(e.getValue()));out.println("raw-equipment "+entries);var equipped=new StringJoiner(" | ");for(var s:EquipmentSlot.values())equipped.add(snapshot(actor.getItemBySlot(s)));out.println("equipped "+equipped);out.println("hands "+snapshot(actor.getMainHandItem())+" | "+snapshot(actor.getOffhandItem()));out.println("empty "+snapshot(ItemStack.EMPTY));}catch(Exception e){throw new AssertionError(e);}}
  void event(EquipmentSlot slot,ItemStack old,ItemStack next){calls++;out.println("equip "+slot.ordinal()+" "+id(old)+" "+id(next));all();if(op.get("fail").getAsBoolean())throw new Stop();if(op.get("mutate").getAsBoolean()){refs[n(op,"mutate_ref")].setCount(n(op,"after_count"));inv.setSelectedSlot(n(op,"after_selected"));inv.setItem(n(op,"replace_slot"),refs[n(op,"replace_ref")]);}}
 }
 static final class Actor extends Player {Data d;Actor(){super(null,null);}@Override public net.minecraft.world.level.GameType gameMode(){return net.minecraft.world.level.GameType.SURVIVAL;}@Override public boolean isSpectator(){return false;}@Override public boolean isCreative(){return false;}@Override public void onEquipItem(EquipmentSlot slot,ItemStack old,ItemStack next){d.event(slot,old,next);}}
 @SuppressWarnings("unchecked")public static void main(String[] args)throws Exception {
  net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var u=Class.forName("sun.misc.Unsafe");unsafe=field(u,"theUnsafe").get(null);allocate=u.getMethod("allocateInstance",Class.class);count=field(ItemStack.class,"count");eqItems=field(EntityEquipment.class,"items");inventory=field(Player.class,"inventory");entityEquipment=field(LivingEntity.class,"equipment");items=new Item[]{Items.AIR,Items.STICK,Items.SHIELD};for(var item:items)item.builtInRegistryHolder().bindComponents(DataComponentMap.EMPTY);Path dir=Path.of(args[1]);
  try(var out=new PrintWriter(Files.newBufferedWriter(dir.resolve(args[0]+".txt")));var lines=Files.lines(dir.resolve("inputs.txt"))){for(var line:(Iterable<String>)lines::iterator){var f=JsonParser.parseString(line).getAsJsonObject();var d=new Data();d.out=out;d.ids.put(ItemStack.EMPTY,0);ItemStack.EMPTY.setCount(0);ItemStack.EMPTY.setPopTime(0);d.actor=make(Actor.class);d.actor.d=d;d.refs=new ItemStack[4];for(int i=0;i<4;i++){var v=f.getAsJsonArray("stacks").get(i).getAsJsonObject();int item=n(v,"item");d.refs[i]=item<0?ItemStack.EMPTY:new ItemStack(items[item],n(v,"count"));if(item>=0)d.refs[i].setPopTime(n(v,"pop"));}d.equipment=new PlayerEquipment(d.actor);d.inv=new Inventory(d.actor,d.equipment);inventory.set(d.actor,d.inv);entityEquipment.set(d.actor,d.equipment);d.inv.setSelectedSlot(n(f,"selected"));for(var e:f.getAsJsonArray("slots")){var p=e.getAsJsonArray();d.inv.setItem(p.get(0).getAsInt(),d.refs[p.get(1).getAsInt()]);}for(var e:f.getAsJsonArray("equipment")){var p=e.getAsJsonArray();d.equipment.set(EquipmentSlot.values()[p.get(0).getAsInt()],d.refs[p.get(1).getAsInt()]);}for(var e:f.getAsJsonArray("raw_entries")){var p=e.getAsJsonArray();((EnumMap<EquipmentSlot,ItemStack>)eqItems.get(d.equipment)).put(EquipmentSlot.values()[p.get(0).getAsInt()],d.refs[p.get(1).getAsInt()]);}d.all();for(var ov:f.getAsJsonArray("ops")){var op=ov.getAsJsonObject();d.op=op;d.calls=0;int a=n(op,"a"),b=n(op,"b"),slot=n(op,"slot");try{switch(op.get("kind").getAsString()){
   case "get-hand":d.refs[b]=d.actor.getItemInHand(InteractionHand.values()[n(op,"hand")]);break;case "set-hand":d.actor.setItemInHand(InteractionHand.values()[n(op,"hand")],d.refs[a]);break;case "get-item":d.refs[b]=d.actor.getItemBySlot(EquipmentSlot.values()[n(op,"equipment")]);break;case "set-item":d.actor.setItemSlot(EquipmentSlot.values()[n(op,"equipment")],d.refs[a]);break;case "set-equipment":d.refs[b]=d.equipment.set(EquipmentSlot.values()[n(op,"equipment")],d.refs[a]);break;case "clear-equipment":d.equipment.clear();break;case "clear":d.inv.clearContent();break;case "select":d.inv.setSelectedSlot(slot);break;case "get":d.refs[b]=d.inv.getItem(slot);break;case "set":d.inv.setItem(slot,d.refs[a]);break;case "count":d.refs[a].setCount(n(op,"amount"));break;case "alias":d.refs[b]=d.refs[a];break;case "copy":d.refs[b]=d.refs[a].copy();break;default:throw new AssertionError();}out.println("result ok "+d.calls);}catch(Stop|IllegalArgumentException|IndexOutOfBoundsException e){out.println("result error "+d.calls);}d.all();}}
  }
 }
}
